w("## 1. Identity\n")
w(f"- Title: {F.title}\n- Product: ForgetSafe, batch CSDS-A / A9, CSE (Data Science)")
w("- Students: " + "; ".join(f"{n} ({r})" for n, r in F.students_upper))
